    // ---------------------------------------------------------------------------------------------
    // Provided — keep this. The tests call runSort(part, nums):
    //   "merge"        -> mergeSort, which must return a new list and leave its input unchanged
    //   "merge_stable" -> mergeSort on records that compare by tens digit only (value / 10),
    //                     returned as their values, so equal keys must keep their input order
    //   "quick"        -> quickSort(nums) in place; the sorted nums is returned
    // ---------------------------------------------------------------------------------------------
    public List<Integer> runSort(String part, int[] nums) {
        List<Integer> out = new ArrayList<>();
        if (part.equals("quick")) {
            quickSort(nums);
            for (int x : nums) out.add(x);
            return out;
        }
        if (part.equals("merge")) {
            List<Integer> input = new ArrayList<>();
            for (int x : nums) input.add(x);
            List<Integer> before = new ArrayList<>(input);
            List<Integer> result = mergeSort(input);
            if (result == input || !input.equals(before)) {
                throw new IllegalStateException("mergeSort must return a new list and leave nums unchanged");
            }
            return result;
        }
        List<Keyed> records = new ArrayList<>();
        for (int x : nums) records.add(new Keyed(x));
        for (Keyed k : mergeSort(records)) out.add(k.value);
        return out;
    }

    static final class Keyed implements Comparable<Keyed> {
        final int value;

        Keyed(int value) { this.value = value; }

        public int compareTo(Keyed other) {
            return Integer.compare(Math.floorDiv(value, 10), Math.floorDiv(other.value, 10));
        }
    }
}
